using UnityEngine;using System;using System.Text;
public static class ValidateSteeringColumn{public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");var s=new StringBuilder();int checks=0;foreach(var source in UnityEngine.Object.FindObjectsByType<PickupController>(FindObjectsSortMode.None)){GameObject copy=null,floor=null;try{floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.localScale=new Vector3(30,1,30);copy=UnityEngine.Object.Instantiate(source.gameObject,new Vector3(10000,.02f,10000),Quaternion.identity);var p=copy.GetComponent<PickupController>();var b=p.GetComponent<BicycleController>();var wheel=p.steeringWheel;var rest=wheel.localRotation;var hub=wheel.localPosition;var normal=rest*Vector3.right;b.SetRidden(true);Physics.SyncTransforms();foreach(float turn in new[]{1f,-1f,0f}){for(int i=0;i<150;i++)b.Drive(0,turn,true,.02f);p.RefreshWheels();if(Vector3.Angle(normal,wheel.localRotation*Vector3.right)>.01f)throw new Exception(source.name+" steering column axis tilted");checks++;if(Vector3.Distance(hub,wheel.localPosition)>.00001f)throw new Exception("Hub moved");checks++;float angle=Quaternion.Angle(rest,wheel.localRotation);if(turn==0?angle>.05f:angle<69f)throw new Exception("Steering rotation/centering failed "+angle);checks++;if(turn!=0&&Mathf.Sign(Mathf.DeltaAngle(0,(Quaternion.Inverse(rest)*wheel.localRotation).eulerAngles.x))!=-Mathf.Sign(turn))throw new Exception("Wheel rotation must oppose steering input around X");checks++;}s.AppendLine(source.name+": column axis and hub fixed, left/right spin and centering pass");}finally{if(copy)UnityEngine.Object.DestroyImmediate(copy);if(floor)UnityEngine.Object.DestroyImmediate(floor);}}System.IO.File.WriteAllText("output/Pickups/steering-column-validation.txt",s.ToString());return "PASS "+checks+" checks\n"+s;}}

